<!doctype html><html lang="si"><head><meta charset="utf-8"><title>Gift card</title><style>body{font-family:'Nirmala UI','Iskoola Pota','Noto Sans Sinhala',Arial,sans-serif;margin:0;background:#eee}.card{width:90mm;margin:10px auto;background:#fff;border:2px dashed #888;padding:12px;text-align:center}.amt{font-size:28px;font-weight:bold}@media print{body{background:#fff}.bar{display:none}.card{margin:0}}</style></head><body>
<div class="bar" style="text-align:center;padding:6px"><button onclick="window.print()">Print</button></div>
<div class="card"><div style="font-size:18px;font-weight:bold"><?= e(setting('business_name', cfg('app_name'))) ?></div><div style="letter-spacing:2px"><?= e(rl('giftcard')) ?></div><div class="amt"><?= e(money($g['initial_amount'])) ?></div><div style="margin:8px 0"><?= Barcode::svg($g['code'], 40, 1.4) ?></div><div style="font-family:monospace;font-size:16px"><?= e($g['code']) ?></div><div style="font-size:11px;color:#555;margin-top:6px"><?= $g['expires_on'] ? e(rl('valid_until')) . ' ' . e($g['expires_on']) : e(rl('no_expiry')) ?> &middot; <?= e(rl('present_card')) ?></div></div></body></html>
